using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Define agent tools
AITool webSearchTool = AIFunctionFactory.Create(
    ([Description("The search query to look up on the web")] string query) =>
    {
        Console.WriteLine($"  [Searching web for: \"{query}\"]");
        // Simulated search results — replace with a real search API (e.g., Bing Search) for production.
        return $"Search results for '{query}':\n" +
               $"1. Overview article on {query} — covers key concepts and recent developments.\n" +
               $"2. Research paper discussing advancements in {query} (2025).\n" +
               $"3. Industry report: market trends related to {query}.";
    },
    "web_search",
    "Searches the web for information on a given query and returns relevant results.");

AITool saveNoteTool = AIFunctionFactory.Create(
    ([Description("Title for the note")] string title,
     [Description("Content of the note")] string content) =>
    {
        noteService.AddNote(title, content);
        Console.WriteLine($"  [Note saved: \"{title}\"]");
        return $"Note '{title}' saved successfully.";
    },
    "save_note",
    "Saves a research note with a title and content for later reference.");

AITool getNotesTool = AIFunctionFactory.Create(
    () =>
    {
        var notes = noteService.GetAllNotes();
        return notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
    },
    "get_notes",
    "Retrieves all saved research notes.");

var tools = new List<AITool> { webSearchTool, saveNoteTool, getNotesTool };

// Create the research agent
var agent = new ChatClientAgent(
    chatClient,
    instructions: "You are a research assistant. Given a topic, search the web for information, " +
        "save key findings as notes, then provide a comprehensive summary. " +
        "Always perform multiple searches to gather diverse perspectives, " +
        "save important findings as notes, and conclude with a final summary of all notes.",
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    topic = "recent advances in quantum computing 2025";
}

Console.WriteLine($"\nResearching: {topic}\n");

var userMessage = $"Research the following topic thoroughly. Search the web multiple times to gather " +
    $"different perspectives, save key findings as notes, then provide a final summary.\n\nTopic: {topic}";

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0.2f,
        MaxOutputTokens = 2048,
    },
};

// Stream the agent's response
await foreach (var update in agent.RunStreamingAsync(userMessage, options: runOptions))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine("\n\n--- Saved Research Notes ---");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"\n📝 {note.Title}");
    Console.WriteLine($"   {note.Content}");
}

Console.WriteLine("\nResearch complete.");

// --- Supporting types ---

public class NoteService
{
    private readonly List<Note> _notes = [];

    public void AddNote(string title, string content) =>
        _notes.Add(new Note(title, content));

    public IReadOnlyList<Note> GetAllNotes() => _notes.AsReadOnly();
}

public record Note(string Title, string Content);

